css:
/* Night Glass v3. The palette is the Chrysaki pair: amethyst and teal. Gold marks the few places that need you. */
[data-workspace-area="conversation"] {
  background-color: #0b1220 !important;
  background-image: linear-gradient(180deg, rgba(11, 18, 32, 0) 72%, rgba(11, 18, 32, 0.7) 100%), linear-gradient(90deg, rgba(11, 18, 32, 0) 0%, rgba(11, 18, 32, 0.5) 24%, rgba(11, 18, 32, 0.5) 76%, rgba(11, 18, 32, 0) 100%), var(--theme-background-image, none) !important;
  background-size: 100% 100%, 100% 100%, cover !important;
  background-position: center, center, center !important;
  background-repeat: no-repeat !important;
  /* The sky is drawn at half size. Pixelated scaling keeps each pixel square. */
  image-rendering: pixelated;
}
/* Image rendering is inherited. The content of the conversation keeps smooth scaling. */
[data-workspace-area="conversation"] > * { image-rendering: auto; }
/* Glass sidebar. A thin light edge replaces a blur, because a blur redraws under motion. */
[data-slot="sidebar-inner"] { background: rgba(13, 21, 38, 0.84) !important; border-right: 1px solid rgba(246, 241, 233, 0.09) !important; }
/* A fading amethyst to teal hairline under the chat header. */
[data-chat-header] { border-bottom: 1px solid transparent; border-image: linear-gradient(90deg, transparent, #583090, #20969c, transparent) 1; }
/* Soft glass cards and popups with a light edge and a faint amethyst glow. */
[data-thread-details-card], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="dialog-popup"] { background: rgba(21, 32, 58, 0.94) !important; border: 1px solid rgba(246, 241, 233, 0.12) !important; border-radius: 14px !important; box-shadow: 0 16px 40px -18px rgba(0, 0, 0, 0.8), 0 0 28px -10px rgba(126, 82, 196, 0.38) !important; }
.chat-markdown-codeblock { border: 1px solid rgba(246, 241, 233, 0.1) !important; border-radius: 12px !important; }
[data-slot="project-monogram"] { border-radius: 50% !important; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #26345a; border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: #3c5a7a; }
[data-slot="scroll-area-thumb"] { background: #26345a !important; border-radius: 8px !important; }
::selection { background: rgba(126, 82, 196, 0.38); color: #f6f1e9; }
/* The environment pill is the only true stage marker, so it gets a clear gold frame. */
[data-environment-identification="pill"] { color: #e8c27a !important; background: rgba(232, 194, 122, 0.08) !important; border: 1px solid rgba(232, 194, 122, 0.65) !important; box-shadow: 0 0 14px -2px rgba(232, 194, 122, 0.45) !important; }

/* The request plate. Four small corner marks frame the bubble. The left wash stays. */
[data-user-message-bubble] { position: relative; border-radius: 6px !important; border: 1px solid rgba(163, 131, 227, 0.34) !important; background-color: rgba(30, 26, 62, 0.82) !important; background-image: linear-gradient(90deg, rgba(163, 131, 227, 0.16), transparent 42%), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)), linear-gradient(rgba(163, 131, 227, 0.7), rgba(163, 131, 227, 0.7)) !important; background-size: 100% 100%, 8px 1px, 1px 8px, 8px 1px, 1px 8px, 8px 1px, 1px 8px, 8px 1px, 1px 8px !important; background-position: 0 0, left 4px top 4px, left 4px top 4px, right 4px top 4px, right 4px top 4px, left 4px bottom 4px, left 4px bottom 4px, right 4px bottom 4px, right 4px bottom 4px !important; background-repeat: no-repeat !important; box-shadow: 0 0 22px -10px rgba(163, 131, 227, 0.55) !important; }
[data-user-message-bubble]::before { content: "✶ OBSERVATION REQUEST"; display: block; white-space: pre; font: 600 9.5px/1.4 ui-monospace, "JetBrains Mono", Consolas, monospace; letter-spacing: 0.16em; color: #b9a2ec; padding-bottom: 5px; margin-bottom: 6px; border-bottom: 1px solid transparent; border-image: linear-gradient(90deg, rgba(163, 131, 227, 0.55), transparent 80%) 1; }
/* A collapsed pasted message has a toggle button as a direct child and no padding of its own. */
[data-user-message-bubble]:has(> button[aria-expanded])::before { content: "✶ TRANSMISSION RELAYED"; padding: 7px 12px 5px; }
/* The log entry. Graph paper, a vernier scale on the left and an amethyst to teal line under the heading. */
[data-message-role="assistant"] .chat-markdown { position: relative; border-radius: 4px 14px 14px 14px !important; border: 1px solid rgba(159, 208, 240, 0.18) !important; border-left: 0 !important; padding: 14px 18px 14px 26px !important; background-color: rgba(12, 20, 38, 0.74) !important; background-image: repeating-linear-gradient(180deg, rgba(163, 131, 227, 0.7) 0 1px, transparent 1px 6px), repeating-linear-gradient(180deg, rgba(111, 211, 214, 0.85) 0 1px, transparent 1px 30px), linear-gradient(rgba(159, 208, 240, 0.045) 1px, transparent 1px), linear-gradient(90deg, rgba(159, 208, 240, 0.045) 1px, transparent 1px) !important; background-size: 5px 100%, 10px 100%, 100% 18px, 18px 100% !important; background-position: 3px 0, 3px 0, 0 0, 0 0 !important; background-repeat: no-repeat, no-repeat, repeat, repeat !important; box-shadow: inset 2px 0 0 rgba(32, 150, 156, 0.7), 0 0 26px -14px rgba(32, 150, 156, 0.6) !important; }
[data-message-role="assistant"] .chat-markdown > :first-child { margin-top: 0 !important; }
[data-message-role="assistant"] .chat-markdown > :last-child { margin-bottom: 0 !important; }
[data-message-role="assistant"] .chat-markdown::before { content: "◐ OBSERVATORY LOG"; display: block; white-space: pre; overflow: hidden; text-overflow: ellipsis; font: 600 9.5px/1.4 ui-monospace, "JetBrains Mono", Consolas, monospace; letter-spacing: 0.14em; color: #9fd0f0; padding-bottom: 7px; margin-bottom: 11px; background: linear-gradient(90deg, #7e52c4, #20969c, transparent 92%) bottom / 100% 2px no-repeat; }
/* Work rows hold markdown too. They stay plain. */
[data-timeline-row-kind="work"] .chat-markdown { background: none !important; border: 0 !important; padding: 0 !important; box-shadow: none !important; }
[data-timeline-row-kind="work"] .chat-markdown::before { content: none; }

/* The composer is a star chart. Polar rings rise from the lower right and rulers frame the chart. The inside looks the same idle and working. */
@property --ng-arc { syntax: "<angle>"; inherits: false; initial-value: 280deg; }
[data-slot="composer-host"] { border-radius: 6px !important; border: 0 !important; background: transparent !important; box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.85), 0 0 0 1px rgba(163, 131, 227, 0.32), -18px -8px 40px -24px rgba(163, 131, 227, 0.45), 18px 8px 40px -24px rgba(111, 211, 214, 0.45) !important; transition: box-shadow 0.4s; }
/* The app draws the glass on the host when a context strip shows, and on the shell when it does not. Both get the chart. */
[data-slot="composer-host"]::before, [data-slot="composer-shell"]:not([data-context-row])::before { border-radius: 6px !important; background-color: rgba(9, 14, 32, 0.92) !important; background-image: radial-gradient(circle at 90% 135%, transparent 0 69px, rgba(163, 131, 227, 0.24) 69px 70px, transparent 70px 119px, rgba(111, 211, 214, 0.2) 119px 120px, transparent 120px 169px, rgba(163, 131, 227, 0.2) 169px 170px, transparent 170px 219px, rgba(111, 211, 214, 0.14) 219px 220px, transparent 220px), repeating-conic-gradient(from 0deg at 90% 135%, rgba(163, 131, 227, 0.12) 0 0.35deg, transparent 0.35deg 15deg), radial-gradient(1.6px 1.6px at 12% 30%, #f6f1e9, transparent), radial-gradient(1.4px 1.4px at 31% 72%, #6fd3d6, transparent), radial-gradient(1.6px 1.6px at 56% 22%, #f6f1e9, transparent), radial-gradient(1.2px 1.2px at 71% 64%, #a383e3, transparent), radial-gradient(1.2px 1.2px at 43% 48%, #6fd3d6, transparent), radial-gradient(ellipse 45% 90% at 0 0, rgba(126, 82, 196, 0.15), transparent 70%), radial-gradient(ellipse 40% 100% at 100% 100%, rgba(32, 150, 156, 0.14), transparent 70%) !important; box-shadow: inset 0 1px 0 rgba(163, 131, 227, 0.22) !important; }
/* The rulers take a colour band through a tick mask. */
[data-slot="composer-host"]:not(:has([data-composer-banner-surface="attached"]))::after { content: ""; display: block !important; inset: 0 !important; border: 0 !important; border-radius: 6px !important; pointer-events: none; opacity: 0.6; background: linear-gradient(90deg, #a383e3, #6fd3d6) !important; -webkit-mask: repeating-linear-gradient(90deg, #000 0 1px, transparent 1px 12px) 0 0 / 100% 4px no-repeat, repeating-linear-gradient(90deg, #000 0 1px, transparent 1px 60px) 0 0 / 100% 9px no-repeat, repeating-linear-gradient(180deg, #000 0 1px, transparent 1px 12px) 0 0 / 4px 100% no-repeat, repeating-linear-gradient(180deg, #000 0 1px, transparent 1px 60px) 0 0 / 9px 100% no-repeat, linear-gradient(#000 0 0) 0 100% / 100% 1px no-repeat; mask: repeating-linear-gradient(90deg, #000 0 1px, transparent 1px 12px) 0 0 / 100% 4px no-repeat, repeating-linear-gradient(90deg, #000 0 1px, transparent 1px 60px) 0 0 / 100% 9px no-repeat, repeating-linear-gradient(180deg, #000 0 1px, transparent 1px 12px) 0 0 / 4px 100% no-repeat, repeating-linear-gradient(180deg, #000 0 1px, transparent 1px 60px) 0 0 / 9px 100% no-repeat, linear-gradient(#000 0 0) 0 100% / 100% 1px no-repeat; }
[data-slot="composer-host"]:focus-within { box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.85), 0 0 0 1px rgba(163, 131, 227, 0.6), -22px -10px 50px -18px rgba(163, 131, 227, 0.9), 22px 10px 50px -18px rgba(111, 211, 214, 0.9) !important; }
/* The agent-working check sits on body. The composer is a sibling of the conversation area in the bundle, so no ancestor inside the conversation can reach it. */
/* A turn start plays two one-shot effects around the composer. A CSS animation starts when its rule begins to match, so each one plays once per turn. Nothing draws inside the composer. */
/* The steady glow is a little stronger than idle. The focus glow below stays stronger still. */
body:has([data-timeline-row-kind="working"], [data-timeline-row-kind="thinking"], [data-timeline-row-kind="work-live"]) [data-slot="composer-host"]:not(:focus-within) { box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.85), 0 0 0 1px rgba(163, 131, 227, 0.42), -18px -8px 40px -22px rgba(163, 131, 227, 0.66), 18px 8px 40px -22px rgba(111, 211, 214, 0.66) !important; }
/* The ping is an outline on the shell. The shell has no overflow clip, so the outline can leave the box. */
body:has([data-timeline-row-kind="working"], [data-timeline-row-kind="thinking"], [data-timeline-row-kind="work-live"]) [data-slot="composer-shell"] { border-radius: 6px; outline: 1px solid transparent; animation: ng-ping 1.2s ease-out 1 forwards; }
/* The trace is the free after layer of the shell. It sits 9px outside the shell edge. The mask keeps a 2px ring that starts 1px out, plus a soft 6px glow beyond it. The ring has four edge strips and four corner tiles that follow the 6px radius of the host. */
body:has([data-timeline-row-kind="working"], [data-timeline-row-kind="thinking"], [data-timeline-row-kind="work-live"]) [data-slot="composer-shell"]::after { content: ""; position: absolute; inset: -9px; pointer-events: none; opacity: 0; background: conic-gradient(from calc(var(--ng-arc) - 60deg) at 50% 50%, transparent 0deg, rgba(163, 131, 227, 0.3) 12deg, #a383e3 34deg, #6fd3d6 58deg, transparent 60deg); mask-repeat: no-repeat; mask-size: calc(100% - 30px) 9px, calc(100% - 30px) 9px, 9px calc(100% - 30px), 9px calc(100% - 30px), 15px 15px, 15px 15px, 15px 15px, 15px 15px; mask-position: 15px 0, 15px 100%, 0 15px, 100% 15px, 0 0, 100% 0, 0 100%, 100% 100%; mask-image: linear-gradient(180deg, transparent 0, rgba(0, 0, 0, 0.18) 3px, rgba(0, 0, 0, 0.45) 5.6px, #000 6px, #000 8px, transparent 8.5px), linear-gradient(0deg, transparent 0, rgba(0, 0, 0, 0.18) 3px, rgba(0, 0, 0, 0.45) 5.6px, #000 6px, #000 8px, transparent 8.5px), linear-gradient(90deg, transparent 0, rgba(0, 0, 0, 0.18) 3px, rgba(0, 0, 0, 0.45) 5.6px, #000 6px, #000 8px, transparent 8.5px), linear-gradient(270deg, transparent 0, rgba(0, 0, 0, 0.18) 3px, rgba(0, 0, 0, 0.45) 5.6px, #000 6px, #000 8px, transparent 8.5px), radial-gradient(circle at 15px 15px, transparent 6.5px, #000 7px, #000 9px, rgba(0, 0, 0, 0.45) 9.4px, rgba(0, 0, 0, 0.18) 12px, transparent 15px), radial-gradient(circle at 0 15px, transparent 6.5px, #000 7px, #000 9px, rgba(0, 0, 0, 0.45) 9.4px, rgba(0, 0, 0, 0.18) 12px, transparent 15px), radial-gradient(circle at 15px 0, transparent 6.5px, #000 7px, #000 9px, rgba(0, 0, 0, 0.45) 9.4px, rgba(0, 0, 0, 0.18) 12px, transparent 15px), radial-gradient(circle at 0 0, transparent 6.5px, #000 7px, #000 9px, rgba(0, 0, 0, 0.45) 9.4px, rgba(0, 0, 0, 0.18) 12px, transparent 15px); animation: ng-trace 2.4s ease-in-out 1 forwards; }
@keyframes ng-trace { 0% { --ng-arc: 280deg; opacity: 0; } 6% { opacity: 1; } 85% { opacity: 1; } 100% { --ng-arc: 640deg; opacity: 0; } }
@keyframes ng-ping { from { outline-color: rgba(111, 211, 214, 0.75); outline-offset: 0; } to { outline-color: rgba(111, 211, 214, 0); outline-offset: 14px; } }
/* The two readouts above the composer say only what the CSS can know. */
[data-chat-composer-form] { position: relative; }
[data-chat-composer-form]::before, [data-chat-composer-form]::after { position: absolute; top: -17px; pointer-events: none; font: 600 9.5px/12px ui-monospace, "JetBrains Mono", Consolas, monospace; letter-spacing: 0.16em; white-space: pre; opacity: 0.72; color: transparent; -webkit-background-clip: text; background-clip: text; }
[data-chat-composer-form]::before { content: "NIGHT GLASS · ORRERY CHART"; left: 2px; background-image: linear-gradient(90deg, #a383e3, #6fd3d6); }
[data-chat-composer-form]::after { content: "○ STANDING BY"; right: 2px; background-image: linear-gradient(90deg, #9fd0f0, #f6f1e9); }
body:has([data-timeline-row-kind="working"], [data-timeline-row-kind="thinking"], [data-timeline-row-kind="work-live"]) [data-chat-composer-form]::after { content: "◎ TRACKING"; background-image: linear-gradient(90deg, #6fd3d6, #6fd3d6); }

/* Sidebar orrery. The strip at the top holds a gold sun, an amethyst orbit and a teal orbit. */
[data-slot="sidebar-inner"] { position: relative; background-image: radial-gradient(circle at -40px 110%, transparent 0 139px, rgba(163, 131, 227, 0.12) 139px 140px, transparent 140px 219px, rgba(111, 211, 214, 0.1) 219px 220px, transparent 220px), radial-gradient(3px 3px at 132px calc(100% - 128px), #a383e3, transparent), radial-gradient(2.5px 2.5px at 190px calc(100% - 196px), #6fd3d6, transparent) !important; background-repeat: no-repeat !important; }
[data-slot="sidebar-inner"]::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 80px; z-index: 0; pointer-events: none; background: radial-gradient(circle at 18% 120%, #e8c27a 0 9px, rgba(232, 194, 122, 0.45) 10px, transparent 22px), radial-gradient(ellipse 44% 80% at 18% 120%, transparent 0 calc(100% - 1.5px), rgba(111, 211, 214, 0.5) calc(100% - 1px), transparent 100%), radial-gradient(ellipse 78% 130% at 18% 120%, transparent 0 calc(100% - 1.5px), rgba(163, 131, 227, 0.45) calc(100% - 1px), transparent 100%), radial-gradient(circle 4px at 46% 52%, #6fd3d6, transparent), radial-gradient(circle 4px at 72% 40%, #a383e3, transparent), linear-gradient(180deg, rgba(40, 30, 80, 0.7), transparent); -webkit-mask: linear-gradient(#000 40%, transparent); mask: linear-gradient(#000 40%, transparent); }
/* The label sits on the after layer, because the count needs the list that comes before it. It stays right aligned so it cannot reach the app title. Idle shows no text. */
[data-slot="sidebar-inner"]::after { content: ""; position: absolute; top: 12px; right: 14px; z-index: 0; pointer-events: none; font: 600 9px/12px ui-monospace, "JetBrains Mono", Consolas, monospace; letter-spacing: 0.14em; color: #6fd3d6; }

/* Thread status. Each row carries a small orbit ring with a planet. The ring follows the status word in the row label. */
[data-thread-item] [data-sidebar-row] { --ng-ring: rgba(159, 208, 240, 0.3); --ng-planet: #9fd0f0; --ng-core: transparent; position: relative; padding-left: 36px !important; border-radius: 12px !important; border-bottom: 1px dashed rgba(159, 208, 240, 0.12); }
[data-thread-item] [data-sidebar-row]::before { content: ""; position: absolute; left: 8px; top: 50%; width: 20px; height: 20px; margin-top: -10px; border-radius: 50%; pointer-events: none; border: 1px solid var(--ng-ring); background: radial-gradient(circle 3.2px at 50% 0, var(--ng-planet) 0 2.6px, transparent 3.2px), radial-gradient(circle, var(--ng-core) 0 2px, transparent 2.6px); }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Working,"], [aria-label$=", Working"], [aria-label*=", Setting up,"], [aria-label$=", Setting up"], [aria-label*=", Goal,"], [aria-label$=", Goal"]) { --ng-ring: rgba(111, 211, 214, 0.55); --ng-planet: #6fd3d6; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Working,"], [aria-label$=", Working"], [aria-label*=", Setting up,"], [aria-label$=", Setting up"], [aria-label*=", Goal,"], [aria-label$=", Goal"])::before { animation: ng-orbit 2.4s linear infinite; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Approval,"], [aria-label$=", Approval"], [aria-label*=", Waiting,"], [aria-label$=", Waiting"]) { --ng-ring: rgba(232, 194, 122, 0.7); --ng-planet: #e8c27a; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Approval,"], [aria-label$=", Approval"], [aria-label*=", Waiting,"], [aria-label$=", Waiting"])::before { animation: ng-halo 2.8s ease-in-out infinite; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Done,"], [aria-label$=", Done"]) { --ng-ring: rgba(163, 131, 227, 0.7); --ng-planet: #a383e3; --ng-core: #a383e3; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Failed,"], [aria-label$=", Failed"], [aria-label*=", Limited,"], [aria-label$=", Limited"]) { --ng-ring: color-mix(in srgb, var(--app-theme-error-foreground, #c9737f) 60%, transparent); --ng-planet: var(--app-theme-error-foreground, #c9737f); }
@keyframes ng-orbit { to { transform: rotate(360deg); } }
@keyframes ng-halo { 0%, 100% { box-shadow: 0 0 0 0 rgba(232, 194, 122, 0); } 50% { box-shadow: 0 0 9px 1px rgba(232, 194, 122, 0.55); } }
[data-thread-item] [data-sidebar-row]:hover { background-color: rgba(30, 40, 76, 0.6) !important; }
[data-thread-item] [data-sidebar-row][class~="bg-sidebar-row-active"], [data-thread-item] [data-sidebar-row][class~="bg-sidebar-row-selected"] { border: 1px solid transparent; background: linear-gradient(rgba(24, 30, 64, 0.94), rgba(24, 30, 64, 0.94)) padding-box, linear-gradient(120deg, #7e52c4, #20969c) border-box !important; box-shadow: 0 0 26px -10px rgba(126, 82, 196, 0.8); }
[data-thread-item] [data-sidebar-row][class~="bg-sidebar-row-active"]::before { box-shadow: 0 0 10px -1px var(--ng-planet); border-color: var(--ng-planet); }
/* The label reads the list. A counter cannot do this, because the app sets content-visibility: auto on each row and that contains counters. The :has() test sees every row, on screen or not. */
[data-slot="sidebar-inner"]:has([data-sidebar-row]:is([aria-label*=", Working,"], [aria-label$=", Working"], [aria-label*=", Setting up,"], [aria-label$=", Setting up"], [aria-label*=", Goal,"], [aria-label$=", Goal"]))::after { content: "◎ TRACKING"; }
[data-slot="sidebar-inner"]:has([data-sidebar-row]:is([aria-label*=", Approval,"], [aria-label$=", Approval"], [aria-label*=", Waiting,"], [aria-label$=", Waiting"]))::after { content: "● NEEDS YOU"; color: #e8c27a; }
/* Reduced motion keeps only the steady glow. The trace and the ping stay off. */
@media (prefers-reduced-motion: reduce) { [data-thread-item] [data-sidebar-row]::before, [data-slot="composer-shell"], [data-slot="composer-shell"]::after { animation: none !important; } }

/* The thread details card is an orrery almanac. Two faint arcs sit in the lower right corner. Each section carries the symbol of a planet. */
[data-thread-details-card] { background: linear-gradient(90deg, #7e52c4, #20969c) top / 100% 2px no-repeat, radial-gradient(circle at 100% 100%, transparent 0 33px, rgba(126, 82, 196, 0.26) 33px 34px, transparent 34px 51px, rgba(32, 150, 156, 0.26) 51px 52px, transparent 52px), linear-gradient(rgba(159, 208, 240, 0.03) 1px, transparent 1px) 0 0 / 100% 16px, linear-gradient(90deg, rgba(159, 208, 240, 0.03) 1px, transparent 1px) 0 0 / 16px 100%, rgba(14, 20, 44, 0.95) !important; border: 1px solid rgba(163, 131, 227, 0.3) !important; box-shadow: 0 24px 50px -20px rgba(0, 0, 0, 0.9), 0 0 36px -14px rgba(126, 82, 196, 0.55) !important; }
[data-thread-details-card] section { border-top-style: dashed !important; border-top-color: rgba(159, 208, 240, 0.16) !important; }
[data-thread-details-card] h3 { font: 600 9.5px/12px ui-monospace, "JetBrains Mono", Consolas, monospace !important; letter-spacing: 0.2em; text-transform: uppercase; color: #9fd0f0 !important; }
[data-thread-details-card] h3::before { margin-right: 7px; font: 400 14px/1 "DejaVu Sans", serif; letter-spacing: 0; color: #6fd3d6; }
#thread-details-workspace-heading::before { content: "♁"; }
#thread-details-version-control-heading::before { content: "☿"; }
#thread-details-servers-heading::before { content: "♃"; }
#thread-details-usage-heading::before { content: "☉"; }
#thread-details-context-heading::before { content: "☾"; }
#thread-details-automations-heading::before { content: "♄"; }
#thread-details-lineage-heading::before { content: "♅"; }
#thread-details-side-chats-heading::before { content: "♆"; }
/* The usage row shows the percent that remains, so the value says so. */
[data-thread-details-card] [aria-label$="% left"] > span:last-child::after { content: " left"; font-weight: 400; color: #b3a998; }
/* Gauges: a graduated track and an amethyst to teal fill. The warning and error fills of the app stay. */
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2), [data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) { height: 7px !important; border-radius: 2px !important; background: repeating-linear-gradient(90deg, rgba(159, 208, 240, 0.28) 0 1px, transparent 1px 10%) 0 100% / 100% 3px no-repeat, rgba(22, 30, 60, 0.95) !important; box-shadow: inset 0 0 0 1px rgba(159, 208, 240, 0.14); overflow: visible !important; }
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2) > span:first-child:not([aria-hidden]), [data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) > span:first-child:not([aria-hidden]) { border-radius: 2px !important; }
